export const TOPICS: Topic[] = RAW_TOPICS as Topic[]

export function getRandomTopic(category?: TopicCategory): Topic {
  const pool = category ? TOPICS.filter(t => t.category === category) : TOPICS
  return pool[Math.floor(Math.random() * pool.length)]
}

export function getTopicsByCategory(category: TopicCategory): Topic[] {
  return TOPICS.filter(t => t.category === category)
}
